import"./chunk-2NFLSA4Y.js";var a={pascalLaw:{theory:{concept:"[[Pascal's law: pressure applied to a liquid or gas in a closed container is transmitted unchanged to every point of it, in all directions.]] So two pistons on the same liquid feel the same extra pressure, p = F\u2081/A\u2081 = F\u2082/A\u2082, and the force on each is proportional to its area."},section:{law:{title:"Pascal's law",text:"[[Liquids hardly compress, so pushing on one place raises the pressure everywhere at once.]] Blaise Pascal described this in the 1650s; the unit of pressure, the pascal, is named after him."},press:{title:"A small force becomes a big one",text:"[[Push the small piston (area A\u2081) with a force F\u2081 and the oil gets the pressure p = F\u2081 / A\u2081.]] The same pressure pushes on the large piston (area A\u2082) with F\u2082 = p \xB7 A\u2082. So F\u2082 / F\u2081 = A\u2082 / A\u2081: a piston with 10 times the diameter has 100 times the area and gives 100 times the force. With a 2 cm and a 20 cm piston, about 118 N lifts a 1200 kg car."},distance:{title:"Nothing comes for free",text:"[[The oil the small piston pushes out goes under the large one: A\u2081 \xB7 s\u2081 = A\u2082 \xB7 s\u2082.]] With a 100 times larger area, the large piston moves 100 times less. The work is the same on both sides: F\u2081 \xB7 s\u2081 = F\u2082 \xB7 s\u2082. The jack does not create energy \u2014 it trades a long, easy push for a short, strong lift, just like a lever or a pulley."},jack:{title:"Pumping: how a jack works",text:"One push of the small piston lifts the load only a little. A valve then stops the oil flowing back, while the small cylinder refills with oil from a reservoir on the return stroke. Push after push, the load climbs. To lift a car 20 cm with 15 cm strokes and a 100 : 1 area ratio, you need about 134 strokes. A larger small piston needs fewer strokes but more force: you choose the trade-off."},everyday:{title:"Hydraulics everywhere",text:"Car brakes use it: your foot pushes a small piston, and the oil presses large pistons at every wheel with the same pressure. Excavators, lifts in car workshops, aircraft controls, dentist's chairs and hydraulic presses that shape metal all work the same way."},pascal:{title:"Blaise Pascal",text:"Blaise Pascal (1623\u20131662) was a French mathematician, physicist and inventor. As a teenager he built one of the first mechanical calculators. In 1648 his brother-in-law carried a mercury barometer up the Puy de D\xF4me mountain for him and showed that air pressure falls with height. A famous demonstration attributed to him: a long thin tube filled with water burst a barrel \u2014 only a few litres of water, but a tall column, so a huge pressure."},check:{title:"Check your understanding",text:"The large piston has 50 times the area of the small one. How much force lifts a 500 kg load? (About 98 N.) How far does the load rise when the small piston moves 10 cm? (2 mm.) Are the pressures under the two pistons different? (No \u2014 they are equal.) Why must you pump many times to lift a car? (Each stroke moves only a little oil under the large piston.) Test each answer in the simulation."}},formula:{pressure:"Pascal's law: the same pressure under both pistons",ratio:"The force grows in the same ratio as the area",area:"Area of a round piston with diameter d",volume:"The oil pushed out by one piston goes under the other",work:"The work in equals the work out (ideal jack)"},variable:{forces:"Forces on the small and the large piston",areas:"Areas of the small and the large piston",diameter:"Diameter of a piston",pressure:"Pressure of the oil",distances:"Distances moved by the two pistons"},assumption:{ideal:"The oil does not compress, the pistons do not leak and there is no friction.",level:"The pistons are at almost the same height, so the weight of the oil itself is ignored.",slow:"The load is lifted slowly: the force shown is exactly what balances it. The pumping rhythm is chosen for the animation; the number of strokes is exact.",scale:"The piston widths are drawn in proportion to their diameters. The force arrows are not to one scale \u2014 the force on the small piston is far smaller; the numbers show the real values."},param:{mass:"Mass of the load",smallDiameter:"Small piston diameter",largeDiameter:"Large piston diameter",stroke:"Length of one stroke",liftHeight:"Lift the load by",gravity:"Gravity",timeStep:"Time step"},hint:{smallDiameter:"The piston you push. A smaller one needs less force but more strokes.",largeDiameter:"The piston that lifts the load.",stroke:"How far the small piston moves in one push."},preset:{person:"Person",car:"Car",elephant:"Elephant"},measure:{requiredForce:"Force needed on the small piston",weight:"Weight of the load",areaRatio:"Area ratio (force gain)",lift:"Height lifted",strokesNeeded:"Strokes needed",pressure:"Pressure of the oil",risePerStroke:"Rise per stroke",strokes:"Strokes so far",smallArea:"Small piston area",largeArea:"Large piston area",workIn:"Work done on the small piston",workOut:"Work done lifting the load",push:"Small piston pushed down"},view:{pressure:"p = {pressure} everywhere in the oil",valve:"valve",target:"target {height}",status:"Lifted {lift} \xB7 stroke {strokes} of {needed}"},graph:{lift:"Height of the load and the small piston's push",work:"Work in and work out"},challenge:{car:{title:"A car with 200 N",description:"On the Earth, lift a car of at least 1200 kg with a force of at most 200 N.",hint:"You need A\u2082/A\u2081 \u2265 59: the large diameter about 8 times the small one."},noAdvantage:{title:"No advantage",description:"Build a press that gives no force advantage at all.",hint:"When are the force on the small piston and the weight equal?"},elephant:{title:"Lift an elephant",description:"On the Earth, lift a 4000 kg load or heavier with a push of at most 300 N.",hint:"You need an area ratio of about 160: a diameter ratio of about 13."},fewStrokes:{title:"Twenty strokes",description:"Lift a car (1200 kg or more) by at least 20 cm in no more than 20 strokes, with a force of at most 1000 N.",hint:"Long strokes and a not-too-large area ratio: between about 12 and 30."},moonCar:{title:"A car on the Moon",description:"On the Moon, lift a car of at least 1200 kg with a force of at most 20 N.",hint:"On the Moon the car weighs about 1940 N, so you need an area ratio of about 100."}}}},s={sim:a};export{s as default,a as sim};
